    if C == 0:
        return []

    colors = set()
    for r in range(R):
        for c in range(C):
            colors.add(grid[r][c])

    wall_color = None
    for color in colors:
        full_rows = any(all(grid[r][c] == color for c in range(C)) for r in range(R))
        full_cols = any(all(grid[r][c] == color for r in range(R)) for c in range(C))
        if full_rows and full_cols:
            wall_color = color
            break

    full_row_indices = [r for r in range(R) if all(grid[r][c] == wall_color for c in range(C))]
    full_col_indices = [c for c in range(C) if all(grid[r][c] == wall_color for r in range(R))]

    output = []
